mapper.select:
SELECT COUNT(*)
FROM TB_TALENT_APPLY A
JOIN TB_TALENT T ON T.TALENT_ID = A.TALENT_ID
JOIN TB_BUSINESS B ON B.BIZ_NO = T.BIZ_NO
WHERE A.APPLY_ID = #{applyId}
  AND B.BIZ_ID = #{bizId}

