WHERE APPLY_ID = #{applyId}
  AND MEMBER_NO = #{memberNo}
  AND STATUS_CD = 'PENDING'

UPDATE TB_TALENT
SET CURRENT_CNT = GREATEST(NVL(CURRENT_CNT, 0) - 1, 0)
WHERE TALENT_ID = #{talentId}
